// Command change-triggers turns row changes of an app table into jobs with
// a database trigger generated by outbox.ChangeTrigger: every insert,
// update and delete, whoever makes it (this program, another service, a
// person at a SQL prompt), writes an outbox entry in the same statement,
// and the relay enqueues it after the commit.
//
// It is the program behind docs/reliability/change-triggers.md: the guide
// copies its regions (marked "snippet:") and task docs:snippets fails when
// they drift.
package main

import (
	"context"
	"errors"
	"fmt"
	"os"

	"github.com/ubgo/sqlb"
	driversqlite "github.com/ubgo/sqlb/contrib/driver-sqlite"
	"github.com/ubgo/workflow"
	"github.com/ubgo/workflow/memory"
	"github.com/ubgo/workflow/sqlstore/outbox"
)

func main() {
	if err := run(context.Background()); err != nil {
		fmt.Fprintln(os.Stderr, "change-triggers:", err)
		os.Exit(1)
	}
}

// run is main without the process exit, so the test drives the same code.
func run(ctx context.Context) (err error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	db, err := driversqlite.Memory()
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, db.Close()) }()
	if _, err := db.ExecContext(ctx, "CREATE TABLE accounts (id TEXT PRIMARY KEY, email TEXT NOT NULL, plan TEXT NOT NULL, password_hash TEXT)"); err != nil {
		return err
	}
	ob, err := outbox.New(db, sqlb.SQLiteDialect{})
	if err != nil {
		return err
	}
	if err := ob.Migrate(ctx); err != nil {
		return err
	}

	fmt.Println("-- install the trigger")
	// snippet:trigger
	trg, err := outbox.ChangeTrigger(sqlb.SQLiteDialect{}, outbox.TriggerSpec{
		Table:    "accounts",
		Ops:      []outbox.ChangeOp{outbox.OnInsert, outbox.OnUpdate, outbox.OnDelete},
		Workflow: "crm.sync",
		Columns:  []string{"id", "email", "plan"}, // never password_hash
		OpField:  "op",
	})
	if err != nil {
		return err
	}
	for _, stmt := range trg.Create { // in a real app: one of your migrations
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			return err
		}
	}
	// snippet:end
	fmt.Println("statements:", len(trg.Create))

	fmt.Println("-- change rows with plain SQL")
	// snippet:changes
	for _, stmt := range []string{
		"INSERT INTO accounts (id, email, plan, password_hash) VALUES ('a1', 'ana@example.com', 'free', 'x')",
		"UPDATE accounts SET plan = 'pro' WHERE id = 'a1'",
		"DELETE FROM accounts WHERE id = 'a1'",
	} {
		if _, err := db.ExecContext(ctx, stmt); err != nil {
			return err
		}
	}
	// snippet:end

	fmt.Println("-- relay to the workers")
	synced := make(chan string, 3)
	mc := memory.New()
	if err := mc.Register(workflow.Workflow{Name: "crm.sync", Steps: []workflow.Step{{
		Name: "push",
		Run: func(ctx context.Context, in []byte) ([]byte, error) {
			synced <- string(in)
			return nil, nil
		},
	}}}); err != nil {
		return err
	}
	if err := mc.Start(ctx); err != nil {
		return err
	}
	defer mc.Stop()
	// snippet:relay
	relay, err := ob.NewRelay(mc)
	if err != nil {
		return err
	}
	n, err := relay.Flush(ctx) // a running app calls relay.Start(ctx) instead
	if err != nil {
		return err
	}
	// snippet:end
	fmt.Println("relayed:", n)
	got := map[string]bool{}
	for range n {
		got[<-synced] = true
	}
	for _, want := range []string{
		`{"id":"a1","email":"ana@example.com","plan":"free","op":"insert"}`,
		`{"id":"a1","email":"ana@example.com","plan":"pro","op":"update"}`,
		`{"id":"a1","email":"ana@example.com","plan":"pro","op":"delete"}`,
	} {
		fmt.Println("synced", want, got[want])
	}
	return nil
}
